const appRoot = document.querySelector("#app");
const THEME_KEY = "chm-theme-preference";
const DEFAULT_COLORS = {
  light: { accent: "#64748B", background: "#F4F5F6", surface: "#FFFFFF", text: "#1F2933" },
  dark: { accent: "#94A3B8", background: "#111315", surface: "#1B1F22", text: "#F3F4F6" },
};
const ASSET_KEYS = ["light_logo", "dark_logo", "favicon", "sso_logo"];
let sharedBranding = null;
let brandDraft = null;
let imageDraft = {};
let canManageServers = false;
let inventoryRefreshTimer = null;
const api = async (path, options = {}) => {
  const response = await fetch(`/api/v1/${path}`, { credentials: "same-origin", headers: { "Content-Type": "application/json", ...options.headers }, ...options });
  const data = response.status === 204 ? null : await response.json().catch(() => null);
  if (!response.ok) throw Object.assign(new Error(data?.message || data?.error || "Request failed"), { status: response.status });
  return data;
};
const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]);
const formData = form => Object.fromEntries(new FormData(form).entries());

function themePreference() {
  const value = localStorage.getItem(THEME_KEY);
  return ["system", "light", "dark"].includes(value) ? value : "system";
}
function effectiveTheme() {
  const choice = themePreference();
  return choice === "system" ? (matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark") : choice;
}
function setThemePreference(value) {
  localStorage.setItem(THEME_KEY, ["system", "light", "dark"].includes(value) ? value : "system");
  applyBranding(sharedBranding);
}
function applyBranding(config) {
  if (!config) return;
  const root = document.documentElement;
  const theme = effectiveTheme();
  const colors = config.colors?.[theme] || DEFAULT_COLORS[theme];
  root.dataset.theme = theme;
  root.dataset.themePreference = themePreference();
  root.style.setProperty("--bg", colors.background);
  root.style.setProperty("--panel", colors.surface);
  root.style.setProperty("--surface", colors.surface);
  root.style.setProperty("--text", colors.text);
  root.style.setProperty("--accent", colors.accent);
  root.style.setProperty("--accent-ink", contrastInk(colors.accent));
  document.title = config.app_name || "Camera Health Monitor";
  let icon = document.querySelector("link[rel='icon']");
  if (!icon) { icon = document.createElement("link"); icon.rel = "icon"; document.head.append(icon); }
  if (config.assets?.favicon) icon.href = `${config.assets.favicon}?v=${encodeURIComponent(config.app_name || "")}`;
  else icon.removeAttribute("href");
  for (const mark of document.querySelectorAll(".brand-logo, .brand-mark")) {
    const size = mark.classList.contains("small") ? "small" : "";
    mark.outerHTML = brandMark(config, size);
  }
}
function contrastInk(hex) {
  const rgb = hex.slice(1).match(/../g).map(v => parseInt(v, 16) / 255).map(v => v <= .03928 ? v / 12.92 : ((v + .055) / 1.055) ** 2.4);
  return (rgb[0] * .2126 + rgb[1] * .7152 + rgb[2] * .0722) > .42 ? "#101316" : "#FFFFFF";
}
matchMedia("(prefers-color-scheme: light)").addEventListener("change", () => { if (themePreference() === "system") applyBranding(sharedBranding); });

function brandMark(config = sharedBranding, size = "") {
  const key = effectiveTheme() === "light" ? "light_logo" : "dark_logo";
  const source = imageDraft[key]?.clear ? null : (imageDraft[key]?.preview || config?.assets?.[key]);
  return source ? `<img class="brand-logo ${size}" src="${escapeHtml(source)}" alt="">` : `<span class="brand-mark ${size}" aria-hidden="true">CH</span>`;
}
function themePicker() {
  return `<label class="theme-picker">Theme<select aria-label="Theme preference" class="theme-select" onchange="setThemePreference(this.value)"><option value="system" ${themePreference() === "system" ? "selected" : ""}>System</option><option value="light" ${themePreference() === "light" ? "selected" : ""}>Light</option><option value="dark" ${themePreference() === "dark" ? "selected" : ""}>Dark</option></select></label>`;
}
window.setThemePreference = setThemePreference;

function showError(form, error) {
  const node = form.querySelector("[data-error]"); node.textContent = error.message; node.hidden = false;
}
function renderSetup() {
  const name = escapeHtml(sharedBranding.app_name);
  appRoot.innerHTML = `<section class="auth-card">${brandMark()}<p class="eyebrow">FIRST RUN</p><h1>Set up your monitor</h1><p class="muted">Create the local administrator account. This setup link becomes unavailable after the first account is created.</p>${themePicker()}
    <form id="setup-form"><label>Username<input name="username" autocomplete="username" required maxlength="64"></label><label>Password<input name="password" type="password" autocomplete="new-password" required minlength="12"><small>Use at least 12 characters.</small></label><p class="form-error" data-error hidden></p><button class="primary">Create administrator</button></form><small class="auth-app-name">${name}</small></section>`;
  document.querySelector("#setup-form").addEventListener("submit", async event => { event.preventDefault(); const form = event.currentTarget; try { await api("setup/admin", { method: "POST", body: JSON.stringify(formData(form)) }); renderDashboard(); } catch (error) { showError(form, error); } });
}
function renderLogin() {
  const name = escapeHtml(sharedBranding.app_name);
  appRoot.innerHTML = `<section class="auth-card">${brandMark()}<p class="eyebrow">CAMERA OPERATIONS</p><h1>Sign in</h1><p class="muted">Use your local administrator account to continue.</p>${themePicker()}
    <form id="login-form"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p class="form-error" data-error hidden></p><button class="primary">Sign in</button></form>
    <button id="sso-login" class="sso-button" hidden>${sharedBranding.assets?.sso_logo ? `<img src="${escapeHtml(sharedBranding.assets.sso_logo)}" alt="">` : ""}${escapeHtml(sharedBranding.sso_button_text)}</button><small class="auth-app-name">${name}</small></section>`;
  document.querySelector("#login-form").addEventListener("submit", async event => { event.preventDefault(); const form = event.currentTarget; try { await api("auth/login", { method: "POST", body: JSON.stringify(formData(form)) }); renderDashboard(); } catch (error) { showError(form, error); } });
}

const clone = value => JSON.parse(JSON.stringify(value));
function colorFields(theme, config) {
  return `<fieldset class="color-theme"><legend>${theme === "light" ? "Light" : "Dark"} appearance</legend>${["accent", "background", "surface", "text"].map(key => `<div class="color-row"><label for="${theme}-${key}">${key[0].toUpperCase() + key.slice(1)}</label><input id="${theme}-${key}" class="brand-color" type="color" value="${config.colors[theme][key]}" data-theme="${theme}" data-color="${key}" aria-label="${theme} ${key} color"><input class="brand-hex" value="${config.colors[theme][key]}" maxlength="7" pattern="#[0-9A-Fa-f]{6}" data-theme="${theme}" data-color="${key}" aria-label="${theme} ${key} hex value"></div>`).join("")}</fieldset>`;
}
function renderBrandingDialog(config) {
  return `<dialog id="branding-dialog"><form method="dialog" class="dialog-close"><button aria-label="Close">×</button></form><p class="eyebrow">SHARED APPEARANCE</p><h2>Branding and themes</h2><p class="muted">These settings are shared by everyone. Your System, Light, or Dark choice stays in this browser.</p><form id="branding-form"><label>Application name<input name="app_name" maxlength="80" required value="${escapeHtml(config.app_name)}"></label><label>SSO button text<input name="sso_button_text" maxlength="80" required value="${escapeHtml(config.sso_button_text)}"></label><button type="button" class="sso-preview" id="sso-preview">${config.assets?.sso_logo ? `<img src="${escapeHtml(config.assets.sso_logo)}" alt="">` : ""}<span>${escapeHtml(config.sso_button_text)}</span></button><small>Preview of the sign-in button (activated when OIDC is configured).</small><div class="color-grid">${colorFields("light", config)}${colorFields("dark", config)}</div><div class="asset-grid">${ASSET_KEYS.map(key => `<label>${key.replaceAll("_", " ")}<input type="file" accept="image/png,image/jpeg" data-asset="${key}"><small>PNG or JPEG. ${key === "favicon" ? "512 KiB, 512px" : "2 MiB, 2048px"} maximum.</small><button type="button" class="quiet asset-clear" data-clear-asset="${key}">Remove image</button></label>`).join("")}</div><p class="form-error" data-error hidden></p><div class="dialog-actions"><button type="button" class="quiet" id="branding-discard">Discard changes</button><button type="button" class="quiet" id="branding-reset">Reset branding</button><button class="primary">Save branding</button></div></form></dialog>`;
}

async function openWebhooks() {
  const [receivers, catalog, reminderSetting, heartbeatSetting] = await Promise.all([api("webhooks"), api("webhook-events"), canManageServers ? api("webhook-settings") : Promise.resolve({enabled:false}), canManageServers ? api("monitoring/heartbeat") : Promise.resolve({enabled:false,receiver_id:null,interval_seconds:300})]);
  const dialog=document.createElement("dialog");
  dialog.innerHTML=`<form method="dialog" class="dialog-close"><button aria-label="Close">×</button></form><p class="eyebrow">AUTOMATION DELIVERY</p><h2>Webhook receivers</h2><p class="muted">Events use version 1 JSON schemas. Delivery is at least once; deduplicate by event ID.</p>${canManageServers?`<label><input id="webhook-reminders" type="checkbox" ${reminderSetting.enabled?"checked":""}> Send unresolved incident reminders every 24 hours</label><section class="server-form"><h3>External monitor heartbeat</h3><label><input id="heartbeat-enabled" type="checkbox" ${heartbeatSetting.enabled?"checked":""}> Send a heartbeat so an external service can detect a stopped container</label><label>Receiver<select id="heartbeat-receiver"><option value="">Choose receiver</option>${receivers.filter(item=>item.enabled&&item.events.includes("monitoring.heartbeat")).map(item=>`<option value="${escapeHtml(item.id)}" ${item.id===heartbeatSetting.receiver_id?"selected":""}>${escapeHtml(item.name)}</option>`).join("")}</select></label><label>Interval, seconds<input id="heartbeat-interval" type="number" min="60" max="86400" value="${heartbeatSetting.interval_seconds||300}"></label><button type="button" class="quiet" id="save-heartbeat">Save heartbeat</button></section>`:""}<form id="webhook-form" class="server-form" ${canManageServers?"":"hidden"}><label>Receiver name<input name="name" maxlength="100" required></label><label>HTTP(S) destination<input name="url" type="url" placeholder="https://automation.example/webhook" required></label><label>Signing secret (optional, 16–256 characters)<input name="signing_secret" type="password" minlength="16" autocomplete="new-password"></label><label><input type="checkbox" name="clear_signing_secret"> Clear saved signing secret</label><label><input type="checkbox" name="enabled" checked> Receiver enabled</label><fieldset><legend>Events</legend>${catalog.events.map(type=>`<label><input type="checkbox" name="event" value="${escapeHtml(type)}" ${type==="incident.opened"?"checked":""}> ${escapeHtml(type)}</label>`).join("")}</fieldset><p class="form-error" data-error hidden></p><button class="primary" data-submit-label>Add receiver</button></form><h3>Configured receivers</h3><div class="server-list">${receivers.map(item=>`<article class="server-card"><h3>${escapeHtml(item.name)}</h3><p>${escapeHtml(item.url)}</p><small>${escapeHtml(item.events.join(", "))} · ${item.signing_secret_configured?"HMAC enabled":"unsigned"} · ${item.enabled?"enabled":"disabled"}</small><div class="server-actions"><button class="quiet" data-test-webhook="${escapeHtml(item.id)}">Send test</button><button class="quiet" data-history-webhook="${escapeHtml(item.id)}">Delivery history</button>${canManageServers?`<button class="quiet" data-edit-webhook="${escapeHtml(item.id)}">Edit</button><button class="quiet danger" data-delete-webhook="${escapeHtml(item.id)}">Remove</button>`:""}</div></article>`).join("")||"<p class='muted'>No receivers configured.</p>"}<div id="webhook-history"></div></div>`;
  document.body.append(dialog);dialog.showModal();
  dialog.querySelector("#save-heartbeat")?.addEventListener("click",async()=>{try{await api("monitoring/heartbeat",{method:"PUT",body:JSON.stringify({enabled:dialog.querySelector("#heartbeat-enabled").checked,receiver_id:dialog.querySelector("#heartbeat-receiver").value||null,interval_seconds:Number(dialog.querySelector("#heartbeat-interval").value)})});alert("Heartbeat settings saved.");}catch(error){alert(error.message);}});
  dialog.querySelector("#webhook-reminders")?.addEventListener("change",async event=>{try{await api("webhook-settings",{method:"PUT",body:JSON.stringify({enabled:event.currentTarget.checked})});}catch(error){event.currentTarget.checked=!event.currentTarget.checked;alert(error.message);}});
  dialog.querySelector("#webhook-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const values=formData(form);values.events=[...form.querySelectorAll("input[name=event]:checked")].map(input=>input.value);values.enabled=form.elements.enabled.checked;const editId=dialog.dataset.editReceiverId;const clearSecret=form.elements.clear_signing_secret.checked;if(clearSecret)values.signing_secret="";else if(editId&&!values.signing_secret)delete values.signing_secret;delete values.clear_signing_secret;try{await api(editId?`webhooks/${editId}`:"webhooks",{method:editId?"PUT":"POST",body:JSON.stringify(values)});dialog.close();dialog.remove();openWebhooks();}catch(error){showError(form,error);}});
  dialog.addEventListener("click",async event=>{const button=event.target.closest("button");if(!button)return;try{if(button.dataset.testWebhook){const result=await api(`webhooks/${button.dataset.testWebhook}/test`,{method:"POST",body:"{}"});alert(`Test delivery ${result.state} (${result.attempt_count} attempt(s)).`);}if(button.dataset.deleteWebhook){await api(`webhooks/${button.dataset.deleteWebhook}`,{method:"DELETE"});dialog.close();dialog.remove();openWebhooks();}if(button.dataset.editWebhook){const item=receivers.find(value=>value.id===button.dataset.editWebhook),form=dialog.querySelector("#webhook-form");dialog.dataset.editReceiverId=item.id;form.elements.name.value=item.name;form.elements.url.value=item.url;form.elements.enabled.checked=item.enabled;form.elements.clear_signing_secret.checked=false;for(const input of form.querySelectorAll("input[name=event]"))input.checked=item.events.includes(input.value);form.querySelector("[data-submit-label]").textContent="Save receiver";form.scrollIntoView({behavior:"smooth",block:"start"});}if(button.dataset.historyWebhook){const rows=await api(`webhooks/${button.dataset.historyWebhook}/deliveries`);dialog.querySelector("#webhook-history").innerHTML=`<h3>Recent deliveries</h3>${rows.map(row=>`<p>${escapeHtml(row.event_type)} · ${escapeHtml(row.state)} · ${row.attempt_count} attempt(s) · ${escapeHtml(row.error_code||row.http_status||"")}</p>`).join("")||"<p class='muted'>No deliveries yet.</p>"}`;}}catch(error){alert(error.message);}});
}
function renderApiTokensDialog() {
  const scopes = ["health:read", "history:read", "incidents:acknowledge", "checks:run", "maintenance:read", "maintenance:write", "servers:read", "servers:write", "cameras:read", "cameras:write", "webhooks:read", "webhooks:write", "branding:write", "auth:manage", "tokens:manage"];
  return `<dialog id="tokens-dialog"><form method="dialog" class="dialog-close"><button aria-label="Close">×</button></form><p class="eyebrow">AUTOMATION ACCESS</p><h2>API tokens</h2><p class="muted">Token values are shown once. Choose only the permissions this integration needs.</p><form id="token-form"><label>Token name<input name="name" maxlength="80" required placeholder="Nightly health check"></label><label>Maximum role<select name="role"><option value="operator">Operator</option><option value="administrator">Administrator</option></select></label><fieldset><legend>Scopes</legend><div class="token-scopes">${scopes.map((scope,index)=>`<label><input type="checkbox" name="scope" value="${scope}" ${index===0?"checked":""}> ${scope}</label>`).join("")}</div></fieldset><label>Expires at <span class="optional">(optional, your local time)</span><input name="expires_at" type="datetime-local"></label><p class="form-error" data-error hidden></p><button class="primary">Issue token</button></form><section id="new-token" hidden><h3>Copy this token now</h3><p class="muted">This secret will not be displayed again.</p><input id="new-token-value" readonly aria-label="New API token"><button type="button" class="quiet" id="copy-token">Copy token</button></section><h3>Issued tokens</h3><div id="token-list" class="token-list"></div></dialog>`;
}
async function refreshTokens() {
  const list = document.querySelector("#token-list");
  const items = await api("admin/api-tokens");
  list.innerHTML = items.map(token => `<article class="token-row"><div><strong>${escapeHtml(token.name)}</strong><small>${escapeHtml(token.role)} · ${escapeHtml(token.scopes.join(", "))}<br>Created ${escapeHtml(token.created_at)}${token.expires_at ? ` · expires ${new Date(token.expires_at).toISOString()}` : " · never expires"}${token.revoked_at ? ` · revoked ${escapeHtml(token.revoked_at)}` : ""}</small></div>${token.revoked_at ? "" : `<button class="quiet revoke-token" data-id="${token.id}">Revoke</button>`}</article>`).join("") || `<p class="muted">No API tokens have been issued.</p>`;
  list.querySelectorAll(".revoke-token").forEach(button => button.addEventListener("click", async () => { await api(`admin/api-tokens/${button.dataset.id}`, {method:"DELETE"}); await refreshTokens(); }));
}
function updateBrandDraftFromForm(form) {
  brandDraft.app_name = form.elements.app_name.value;
  brandDraft.sso_button_text = form.elements.sso_button_text.value;
  for (const node of form.querySelectorAll(".brand-hex")) {
    const value = node.value.trim(); if (/^#[0-9a-fA-F]{6}$/.test(value)) brandDraft.colors[node.dataset.theme][node.dataset.color] = value.toUpperCase();
  }
  for (const key of ASSET_KEYS) if (imageDraft[key]?.clear) brandDraft.assets[key] = null; else if (imageDraft[key]?.preview) brandDraft.assets[key] = imageDraft[key].preview;
  applyBranding(brandDraft);
  const ssoPreview = document.querySelector("#sso-preview");
  if (ssoPreview) ssoPreview.innerHTML = `${brandDraft.assets?.sso_logo ? `<img src="${escapeHtml(brandDraft.assets.sso_logo)}" alt="">` : ""}<span>${escapeHtml(brandDraft.sso_button_text)}</span>`;
  const title = document.querySelector(".wordmark > span:last-child"); if (title) title.textContent = brandDraft.app_name;
  const mark = document.querySelector(".wordmark .brand-logo, .wordmark .brand-mark"); if (mark) mark.outerHTML = brandMark(brandDraft, "small");
}
function bindBrandingDialog(dialog) {
  const form = dialog.querySelector("#branding-form");
  for (const picker of form.querySelectorAll(".brand-color")) picker.addEventListener("input", () => { const hex = form.querySelector(`.brand-hex[data-theme="${picker.dataset.theme}"][data-color="${picker.dataset.color}"]`); hex.value = picker.value.toUpperCase(); updateBrandDraftFromForm(form); });
  for (const input of form.querySelectorAll(".brand-hex")) input.addEventListener("input", () => { if (/^#[0-9a-fA-F]{6}$/.test(input.value)) { form.querySelector(`.brand-color[data-theme="${input.dataset.theme}"][data-color="${input.dataset.color}"]`).value = input.value; updateBrandDraftFromForm(form); } });
  form.elements.app_name.addEventListener("input", () => updateBrandDraftFromForm(form)); form.elements.sso_button_text.addEventListener("input", () => updateBrandDraftFromForm(form));
  for (const input of form.querySelectorAll("[data-asset]")) input.addEventListener("change", () => { const file = input.files[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { imageDraft[input.dataset.asset] = { preview: reader.result, base64: String(reader.result).split(",")[1] }; updateBrandDraftFromForm(form); }; reader.readAsDataURL(file); });
  for (const button of form.querySelectorAll("[data-clear-asset]")) button.addEventListener("click", () => { imageDraft[button.dataset.clearAsset] = { clear: true }; updateBrandDraftFromForm(form); });
  dialog.querySelector("#branding-discard").addEventListener("click", () => { dialog.close(); imageDraft = {}; applyBranding(sharedBranding); renderDashboard(); });
  dialog.querySelector("#branding-reset").addEventListener("click", () => { brandDraft = { app_name: "Camera Health Monitor", sso_button_text: "Sign in with single sign-on", colors: clone(DEFAULT_COLORS), assets: Object.fromEntries(ASSET_KEYS.map(key => [key, null])) }; imageDraft = Object.fromEntries(ASSET_KEYS.map(key => [key, { clear: true }])); form.elements.app_name.value = brandDraft.app_name; form.elements.sso_button_text.value = brandDraft.sso_button_text; for (const node of form.querySelectorAll(".brand-hex,.brand-color")) { const value = brandDraft.colors[node.dataset.theme][node.dataset.color]; node.value = value; } updateBrandDraftFromForm(form); });
  form.addEventListener("submit", async event => { event.preventDefault(); updateBrandDraftFromForm(form); const uploads = Object.fromEntries(Object.entries(imageDraft).map(([key, value]) => [key, value.clear ? null : value.base64]).filter(([, value]) => value !== undefined));
    try { const saved = await api("branding", { method: "PUT", body: JSON.stringify({ app_name: brandDraft.app_name, sso_button_text: brandDraft.sso_button_text, colors: brandDraft.colors, asset_uploads: uploads }) }); sharedBranding = saved; imageDraft = {}; dialog.close(); applyBranding(saved); renderDashboard(); } catch (error) { showError(form, error); }
  });
}

async function renderDashboard() {
  let dashboard; try { dashboard = await api("dashboard"); } catch (error) { if (error.status === 401) return renderLogin(); throw error; }
  sharedBranding = dashboard.branding || sharedBranding;
  canManageServers = dashboard.principal.role === "administrator";
  const name = escapeHtml(sharedBranding.app_name || "Camera Health Monitor");
  appRoot.innerHTML = `<header class="topbar"><a class="wordmark" href="/" aria-label="${name} home">${brandMark(sharedBranding, "small")}<span>${name}</span></a><div class="top-actions">${themePicker()}<span class="user-pill"><span class="status-dot"></span>${escapeHtml(dashboard.principal.username)} · ${escapeHtml(dashboard.principal.role || "administrator")}</span>${dashboard.principal.auth_type !== "oidc" ? '<button class="quiet" id="credentials-open">Account</button>' : ""}${dashboard.principal.role === "administrator" ? '<button class="quiet" id="oidc-open">Single sign-on</button><button class="quiet" id="branding-open">Branding</button><button class="quiet" id="webhooks-open">Webhooks</button><button class="quiet" id="tokens-open">API tokens</button>' : '<button class="quiet" id="webhooks-open">Webhooks</button>'}<button class="quiet" id="logout">Sign out</button></div></header>
    <section class="content"><div class="page-heading"><div><p class="eyebrow">OVERVIEW</p><h1>Camera health</h1><p class="muted">Manage recorder connections and discover camera inventory.</p></div><span class="live-label"><i></i> INVENTORY</span></div><div class="summary-grid"><article class="metric"><span>Servers</span><strong>${dashboard.summary.servers}</strong><small>Configured recorders</small></article><article class="metric"><span>Cameras</span><strong>${dashboard.summary.cameras}</strong><small>Discovered cameras</small></article><article class="metric"><span>Needs attention</span><strong>${dashboard.summary.failures + dashboard.summary.warnings + (dashboard.summary.monitoring||0)}</strong><small>${dashboard.summary.failures} failures · ${dashboard.summary.warnings} warnings · ${dashboard.summary.monitoring||0} monitoring</small></article></div><section class="inventory-section"><div class="section-heading"><h2>Active incidents</h2><button class="quiet" id="history-toggle">Show 90-day history</button></div><div id="incident-list" class="camera-list">Loading incidents…</div><div id="incident-history" hidden></div></section><section class="inventory-section"><div class="section-heading"><h2>Maintenance windows</h2><p class="muted">Checks continue during maintenance; health notifications are suppressed until it ends.</p></div>${canManageServers?`<form id="maintenance-form" class="server-form"><label>Scope<select name="entity_type"><option value="camera">Camera</option><option value="server">Recorder server</option></select></label><label>Target<select name="entity_id" required></select></label><label>Reason<input name="reason" required maxlength="500" placeholder="Planned camera replacement"></label><label>Starts<input name="starts_at" type="datetime-local" required></label><label>Ends<input name="ends_at" type="datetime-local" required></label><p class="form-error" data-error hidden></p><button class="primary">Schedule maintenance</button></form>`:""}<div id="maintenance-list" class="camera-list">Loading maintenance…</div></section><section class="server-section"><div class="section-heading"><h2>Recorder servers</h2><p class="muted">Credentials are encrypted at rest. Secret values are write-only and never returned.</p></div>${canManageServers ? `<form id="server-form" class="server-form"><label>Display name<input name="name" required maxlength="100" placeholder="Main recorder"></label><label>Host<input name="host" required maxlength="253" placeholder="192.0.2.20 or recorder.example"></label><label>Native recorder port (optional)<input name="port" type="number" min="1" max="65535"></label><label>Web Service scheme<select name="web_scheme"><option value="http">HTTP</option><option value="https">HTTPS</option></select></label><label>Web Service port<input name="web_port" type="number" min="1" max="65535" value="80" required></label><label>Username<input name="username" autocomplete="username"></label><label>Password (optional)<input name="password" type="password" autocomplete="new-password"></label><label>Live interval (minutes)<input name="live_interval_minutes" type="number" min="1" max="1440" value="5" required></label><label>Recording interval (minutes)<input name="recording_interval_minutes" type="number" min="1" max="1440" value="60" required></label><label>Recording lookback (hours)<input name="recording_lookback_hours" type="number" min="1" max="720" value="24" required></label><label><input type="checkbox" name="recording_expected" checked> Alert when recordings are expected but none are found</label><p class="form-error" data-error hidden></p><button class="primary">Add recorder</button></form>` : ""}<p class="integration-notice"><strong>ExacqVision Web Service support is enabled.</strong> Authentication, camera discovery, live JPEG delivery, recording search, and recorded playback use the 21.12 Web Client interface. Live samples are decoded; the source does not expose a capture timestamp, so wall-clock freshness is reported as unverified. Confirm playback behavior with one live and one recording check after deployment.</p><div id="server-list" class="server-list">Loading servers…</div></section><section class="inventory-section"><h2>Camera inventory</h2><p id="scheduler-state" class="muted">Checking scheduled monitoring…</p><div id="camera-list" class="camera-list"></div></section><footer>Live samples are decoded ephemerally and removed when each check completes. No footage or thumbnails are retained.</footer></section>
    ${dashboard.principal.auth_type !== "oidc" ? `<dialog id="credentials-dialog"><form method="dialog" class="dialog-close"><button aria-label="Close">×</button></form><p class="eyebrow">ACCOUNT SECURITY</p><h2>Administrator credentials</h2><form id="credentials-form"><label>Current password<input name="current_password" type="password" autocomplete="current-password" required></label><label>Username<input name="username" value="${escapeHtml(dashboard.principal.username)}" autocomplete="username" required maxlength="64"></label><label>New password <span class="optional">(leave blank to keep current)</span><input name="new_password" type="password" autocomplete="new-password" minlength="12"></label><p class="form-error" data-error hidden></p><button class="primary">Save credentials</button></form></dialog>` : ""}${dashboard.principal.role === "administrator" ? renderBrandingDialog(sharedBranding) + renderApiTokensDialog() : ""}${dashboard.principal.role === "administrator" ? `<dialog id="oidc-dialog"><form method="dialog" class="dialog-close"><button aria-label="Close">×</button></form><p class="eyebrow">ACCESS CONTROL</p><h2>OpenID Connect</h2><form id="oidc-form"><label><input type="checkbox" name="enabled"> Enable single sign-on</label><label>Issuer URL<input name="issuer" type="url" required></label><label>Client ID<input name="client_id" required></label><label>Client secret<input name="client_secret" type="password" placeholder="Leave blank to keep saved secret"></label><label>Role/group claim name<input name="role_claim" required value="groups"></label><label>Administrator claim values<input name="administrator_values"></label><label>Operator claim values<input name="operator_values"></label><p class="form-error" data-error hidden></p><button class="primary">Save single sign-on</button></form></dialog>` : ""}`;
  document.querySelector("#logout").addEventListener("click", async () => { await api("auth/logout", { method: "POST" }); renderLogin(); });
  const dialog = document.querySelector("#branding-dialog"); if (dialog) { document.querySelector("#branding-open").addEventListener("click", () => { brandDraft = clone(sharedBranding); imageDraft = {}; dialog.showModal(); }); bindBrandingDialog(dialog); }
  const credentials = document.querySelector("#credentials-dialog"); if (credentials) {
    document.querySelector("#credentials-open").addEventListener("click", () => credentials.showModal());
    document.querySelector("#credentials-form").addEventListener("submit", async event => { event.preventDefault(); const form=event.currentTarget; try { await api("admin/credentials", {method:"PUT", body:JSON.stringify(formData(form))}); credentials.close(); renderDashboard(); } catch(error) { showError(form,error); } });
  }
  const oidcDialog = document.querySelector("#oidc-dialog"); if (oidcDialog) {
    document.querySelector("#oidc-open").addEventListener("click", async () => { const form=document.querySelector("#oidc-form"); const config=await api("admin/auth/oidc"); form.elements.enabled.checked=config.enabled; form.elements.issuer.value=config.issuer; form.elements.client_id.value=config.client_id; form.elements.role_claim.value=config.role_claim; form.elements.administrator_values.value=config.administrator_values.join(", "); form.elements.operator_values.value=config.operator_values.join(", "); oidcDialog.showModal(); });
    document.querySelector("#oidc-form").addEventListener("submit", async event => { event.preventDefault(); const form=event.currentTarget, fields=formData(form); const payload={enabled:form.elements.enabled.checked,issuer:fields.issuer,client_id:fields.client_id,client_secret:fields.client_secret,role_claim:fields.role_claim,administrator_values:fields.administrator_values.split(",").map(x=>x.trim()).filter(Boolean),operator_values:fields.operator_values.split(",").map(x=>x.trim()).filter(Boolean)}; try { await api("admin/auth/oidc",{method:"PUT",body:JSON.stringify(payload)}); oidcDialog.close(); } catch(error) { showError(form,error); } });
  }
  const tokensDialog = document.querySelector("#tokens-dialog"); if (tokensDialog) {
    document.querySelector("#tokens-open").addEventListener("click", async () => { await refreshTokens(); tokensDialog.showModal(); });
    const tokenForm = document.querySelector("#token-form");
    tokenForm.elements.role.addEventListener("change", () => { const operatorScopes = new Set(["health:read", "history:read", "incidents:acknowledge", "checks:run", "maintenance:read"]); for (const input of tokenForm.querySelectorAll("input[name=scope]")) { if (!operatorScopes.has(input.value) && tokenForm.elements.role.value === "operator") { input.checked = false; input.disabled = true; } else input.disabled = false; } });
    tokenForm.addEventListener("submit", async event => { event.preventDefault(); const values = formData(tokenForm); const selected = [...tokenForm.querySelectorAll("input[name=scope]:checked")].map(input => input.value); const expiresAt = values.expires_at ? new Date(values.expires_at).toISOString() : null; try { const issued = await api("admin/api-tokens", {method:"POST", body:JSON.stringify({name:values.name,role:values.role,scopes:selected,expires_at:expiresAt})}); document.querySelector("#new-token").hidden = false; document.querySelector("#new-token-value").value = issued.token; await refreshTokens(); } catch(error) { showError(tokenForm,error); } });
    document.querySelector("#copy-token").addEventListener("click", async () => { await navigator.clipboard.writeText(document.querySelector("#new-token-value").value); });
  }
  const serverForm = document.querySelector("#server-form");
  document.querySelector("#webhooks-open")?.addEventListener("click",()=>openWebhooks().catch(error=>alert(error.message)));
  if (serverForm) serverForm.elements.web_scheme.addEventListener("change", () => { const port=serverForm.elements.web_port; if(port.value==="80"||port.value==="443") port.value=serverForm.elements.web_scheme.value==="https"?"443":"80"; });
  if (serverForm) serverForm.addEventListener("submit", async event => { event.preventDefault(); const form=event.currentTarget; try { const values=formData(form); values.port=values.port?Number(values.port):null; values.web_port=Number(values.web_port); values.defaults={live_interval_minutes:Number(values.live_interval_minutes),recording_interval_minutes:Number(values.recording_interval_minutes),recording_lookback_hours:Number(values.recording_lookback_hours),recording_expected:form.elements.recording_expected.checked}; delete values.live_interval_minutes; delete values.recording_interval_minutes; delete values.recording_lookback_hours; await api("servers",{method:"POST",body:JSON.stringify({...values,adapter:"exacq"})}); await renderServerInventory(); form.reset(); } catch(error) { showError(form,error); } });
  await renderServerInventory();
  if (inventoryRefreshTimer) clearInterval(inventoryRefreshTimer);
  inventoryRefreshTimer = setInterval(() => {
    const cameraList = document.querySelector("#camera-list");
    if (cameraList && !cameraList.contains(document.activeElement)) renderServerInventory().catch(() => {});
  }, 15000);
  applyBranding(sharedBranding);
}

function capabilityBadge(capability) { const status=capability?.status||"untested"; return `<span class="capability ${escapeHtml(status)}"><b>${escapeHtml(status)}</b><small>${escapeHtml(capability?.detail||"No probe has run.")}</small></span>`; }
async function renderServerInventory() {
  const [servers,cameras,monitoring,incidents,maintenance]=await Promise.all([api("servers"),api("cameras"),api("monitoring"),api("incidents"),api("maintenance")]);
  const incidentList=document.querySelector("#incident-list");
  if(incidentList)incidentList.innerHTML=incidents.length?incidents.map(i=>`<article class="camera-row"><div><b>${escapeHtml(i.severity.toUpperCase())} · ${escapeHtml(i.reason.replaceAll("_"," "))}</b><small>${escapeHtml(i.entity_type)} ${escapeHtml(i.entity_id)} · ${escapeHtml(i.check_type)} · opened ${escapeHtml(i.opened_at)}</small><span class="check-result">${i.suppressed?"Notifications suppressed · ":""}${i.acknowledged_at?`Reviewed by ${escapeHtml(i.acknowledged_by)} at ${escapeHtml(i.acknowledged_at)}`:"Not acknowledged"} · ${i.transitions.length} transitions</span></div><div><button class="quiet" data-incident-detail="${escapeHtml(i.id)}">Details</button>${i.acknowledged_at?"":`<button class="quiet" data-incident-ack="${escapeHtml(i.id)}">Acknowledge</button>`}</div></article>`).join(""):`<div class="empty-state"><h3>No active incidents</h3><p>Health warnings and failures will appear here. Unknown provider results are kept separate from camera incidents.</p></div>`;
  const maintenanceList=document.querySelector("#maintenance-list");
  if(maintenanceList)maintenanceList.innerHTML=maintenance.length?maintenance.map(window=>`<article class="camera-row"><div><b>${escapeHtml(window.state.toUpperCase())} · ${escapeHtml(window.entity_type)} ${escapeHtml(window.entity_id)}</b><small>${escapeHtml(window.reason)} · ${escapeHtml(window.starts_at)} – ${escapeHtml(window.ends_at)}</small></div>${canManageServers&&window.state!=="ended"?`<button class="quiet" data-maintenance-end="${escapeHtml(window.id)}">End now</button>`:""}</article>`).join(""):`<p class="muted">No maintenance windows recorded.</p>`;
  const maintenanceForm=document.querySelector("#maintenance-form");
  if(maintenanceForm){const type=maintenanceForm.elements.entity_type,target=maintenanceForm.elements.entity_id;const refreshTargets=()=>{const rows=type.value==="server"?servers.map(x=>[x.id,x.name]):cameras.map(x=>[x.id,x.name]);target.innerHTML=rows.map(([id,label])=>`<option value="${escapeHtml(id)}">${escapeHtml(label)}</option>`).join("");};type.onchange=refreshTargets;refreshTargets();maintenanceForm.onsubmit=async event=>{event.preventDefault();const values=formData(maintenanceForm);try{await api("maintenance",{method:"POST",body:JSON.stringify({...values,starts_at:new Date(values.starts_at).toISOString(),ends_at:new Date(values.ends_at).toISOString()})});maintenanceForm.reset();refreshTargets();await renderServerInventory();}catch(error){showError(maintenanceForm,error);}};}
  if(maintenanceList)maintenanceList.onclick=async event=>{const button=event.target.closest("[data-maintenance-end]");if(!button)return;try{await api(`maintenance/${button.dataset.maintenanceEnd}`,{method:"DELETE"});await renderServerInventory();}catch(error){alert(error.message);}};
  const historyToggle=document.querySelector("#history-toggle");
  if(historyToggle)historyToggle.onclick=async()=>{const pane=document.querySelector("#incident-history");pane.hidden=!pane.hidden;if(!pane.hidden){const history=await api("history?days=90");pane.innerHTML=history.incidents.length?history.incidents.map(i=>`<article class="camera-row"><div><b>${escapeHtml(i.status)} · ${escapeHtml(i.severity)} · ${escapeHtml(i.reason.replaceAll("_"," "))}</b><small>${escapeHtml(i.check_type)} · ${escapeHtml(i.opened_at)}${i.resolved_at?` – ${escapeHtml(i.resolved_at)}`:" · active"}</small><details><summary>${i.transitions.length} transitions</summary>${i.transitions.map(t=>`<p>${escapeHtml(t.created_at)} · ${escapeHtml(t.event)}${t.reason?` · ${escapeHtml(t.reason)}`:""}${t.actor?` · ${escapeHtml(t.actor)}`:""}</p>`).join("")}</details></div></article>`).join(""):`<p class="muted">No incident history in the last 90 days.</p>`;historyToggle.textContent="Hide history";}else historyToggle.textContent="Show 90-day history";};
  if(incidentList)incidentList.onclick=async event=>{const ack=event.target.closest("[data-incident-ack]");const detail=event.target.closest("[data-incident-detail]");try{if(ack){await api(`incidents/${ack.dataset.incidentAck}/acknowledge`,{method:"POST",body:"{}"});await renderServerInventory();}if(detail){const i=await api(`incidents/${detail.dataset.incidentDetail}`);alert(`${i.reason} (${i.severity})\nOpened: ${i.opened_at}\n${i.transitions.map(t=>`${t.created_at}: ${t.event}${t.actor?` by ${t.actor}`:""}`).join("\n")}`);}}catch(error){alert(error.message);}};
  const schedulerState=document.querySelector("#scheduler-state");
  if(schedulerState)schedulerState.textContent=`Monitor service ${monitoring.monitor.state}; process ${monitoring.monitor.liveness}; last progress ${monitoring.monitor.last_progress_at||"not available"}${monitoring.monitor.last_error_code?` · diagnostic ${monitoring.monitor.last_error_code}`:""}. Scheduled checks ${monitoring.scheduler.running?"are running":"are not running"}; last scheduler tick ${monitoring.scheduler.last_tick_at||"not available"}.`;
  const list=document.querySelector("#server-list");
  list.innerHTML=servers.length?servers.map(server=>`<article class="server-card"><div class="server-card-heading"><div><h3>${escapeHtml(server.name)}</h3><p>${escapeHtml(server.host)} · Web Service ${escapeHtml(server.web_scheme||"http")}://${escapeHtml(server.host)}:${server.web_port||80} · ${server.credentials_configured?"Credentials saved":"No credentials saved"}</p></div><span class="status-pill ${escapeHtml(server.discovery_status)}">Discovery ${escapeHtml(server.discovery_status)}</span></div><div class="capability-grid">${Object.entries(server.capabilities).map(([name,cap])=>`<div><b>${escapeHtml(name.replaceAll("_"," "))}</b>${capabilityBadge(cap)}</div>`).join("")}</div><div class="server-actions"><button class="primary" data-action="discover" data-id="${escapeHtml(server.id)}">Refresh camera inventory</button><button class="quiet" data-action="recording-check" data-id="${escapeHtml(server.id)}">Run recording checks</button>${canManageServers?`<button class="quiet" data-action="probe" data-id="${escapeHtml(server.id)}">Test connection</button><button class="quiet" data-action="edit" data-id="${escapeHtml(server.id)}">Edit</button><button class="quiet danger" data-action="remove" data-id="${escapeHtml(server.id)}">Remove</button>`:""}</div><small>Last discovery: ${escapeHtml(server.last_discovery_at||"Never")}</small></article>`).join(""):`<div class="empty-state"><div class="empty-icon" aria-hidden="true">＋</div><h2>No servers configured</h2><p>Add a recorder connection above. Test the configured Web Service connection before relying on scheduled checks.</p></div>`;
  const cameraList=document.querySelector("#camera-list");
  const monitoringById=new Map(monitoring.cameras.map(item=>[item.camera_id,item]));
  cameraList.innerHTML=cameras.length?cameras.map(camera=>{
    const live=camera.live_status||{},rec=camera.recording_status||{},schedule=monitoringById.get(camera.id)||{};
    const lastSuccess=[live.last_success_at&&`Live last success ${live.last_success_at}`,rec.last_success_at&&`Recording last success ${rec.last_success_at}`].filter(Boolean).join(" · ")||"No successful checks yet";
    const liveText=live.state==="pending_confirmation"?"failure awaiting 30-second confirmation":`${live.health||"unknown"}${live.state==="stale"?" (stale)":""}${live.freshness_verified===false?" · freshness unverified":""}`;
    const recText=`${rec.health||"unknown"}${rec.state==="stale"?" (stale)":""}${rec.reason?` · ${rec.reason.replaceAll("_"," ")}`:""} · newest recording ${rec.newest_recording_at||"none"}`;
    const activeMaintenance=(camera.maintenance||[]).filter(w=>w.state!=="ended");
    return `<article class="camera-row ${camera.disappeared?"disappeared":""}"><div><b>${escapeHtml(camera.name)}</b><small>${escapeHtml(camera.remote_id)} · server ${escapeHtml(camera.server_id.slice(0,8))}</small>${camera.disabled?`<span class="check-result">Disabled in ExacqVision · excluded from scheduled checks</span>`:camera.connection_state==="disconnected"?`<span class="check-result">Recorder reports this camera disconnected · live verification will determine camera health</span>`:""}${camera.exclusion?.excluded?`<span class="check-result">Excluded from scheduled monitoring · ${escapeHtml(camera.exclusion.reason)}</span>`:""}${activeMaintenance.map(w=>`<span class="check-result">${escapeHtml(w.state)} maintenance · ${escapeHtml(w.reason)} · through ${escapeHtml(w.ends_at)}</span>`).join("")}<span class="check-result" id="check-${escapeHtml(camera.id)}">Live ${escapeHtml(liveText)} · Recording ${escapeHtml(recText)} · next ${escapeHtml(schedule.next_due_at?.live||"not scheduled")} · run ${escapeHtml(schedule.execution_state?.live?.state||"idle")} · last run ${escapeHtml(schedule.last_execution?.live||"never")}${schedule.active_job_id?` · job ${escapeHtml(schedule.active_job_id)}`:""}</span><small>${escapeHtml(lastSuccess)}</small>${canManageServers&&!camera.disappeared?`<div class="server-form"><label>Live interval (minutes)<input data-setting="live_interval_minutes" data-camera="${escapeHtml(camera.id)}" type="number" min="1" max="1440" value="${escapeHtml(camera.overrides.live_interval_minutes||"")}" placeholder="${escapeHtml(camera.settings.live_interval_minutes||5)}"></label><label>Recording interval (minutes)<input data-setting="recording_interval_minutes" data-camera="${escapeHtml(camera.id)}" type="number" min="1" max="1440" value="${escapeHtml(camera.overrides.recording_interval_minutes||"")}" placeholder="${escapeHtml(camera.settings.recording_interval_minutes||60)}"></label><label>Recording lookback (hours)<input data-setting="recording_lookback_hours" data-camera="${escapeHtml(camera.id)}" type="number" min="1" max="720" value="${escapeHtml(camera.overrides.recording_lookback_hours||"")}" placeholder="${escapeHtml(camera.settings.recording_lookback_hours||24)}"></label><label>Missing recording alert<select data-setting="recording_expected" data-camera="${escapeHtml(camera.id)}"><option value="default" ${camera.overrides.recording_expected===undefined?"selected":""}>Use server default</option><option value="true" ${camera.overrides.recording_expected===true?"selected":""}>Alert when none are found</option><option value="false" ${camera.overrides.recording_expected===false?"selected":""}>No alert for missing footage</option></select></label><button class="quiet" data-save-settings="${escapeHtml(camera.id)}">Save camera overrides</button><label>Exclusion reason<input data-exclusion-reason="${escapeHtml(camera.id)}" maxlength="500" value="${escapeHtml(camera.exclusion?.reason||"")}" placeholder="Why this camera is intentionally offline"></label><button class="quiet" data-exclusion-toggle="${escapeHtml(camera.id)}" data-excluded="${camera.exclusion?.excluded?"true":"false"}">${camera.exclusion?.excluded?"Restore monitoring":"Exclude camera"}</button></div>`:""}</div>${camera.disappeared||camera.disabled?"":`<div><button class="quiet" data-live-check="${escapeHtml(camera.id)}">Run live check</button><button class="quiet" data-recording-check="${escapeHtml(camera.id)}">Run recording check</button></div>`}</article>`;
  }).join(""):`<p class="muted">No cameras discovered yet.</p>`;
  cameraList.onclick=async event=>{
    const button=event.target.closest("button");if(!button)return;
    const cameraId=button.dataset.liveCheck||button.dataset.recordingCheck,saveId=button.dataset.saveSettings,exclusionId=button.dataset.exclusionToggle;
    if(exclusionId){const excluded=button.dataset.excluded==="true",reason=cameraList.querySelector(`[data-exclusion-reason="${CSS.escape(exclusionId)}"]`).value;try{await api(`cameras/${exclusionId}/exclusion`,{method:"PUT",body:JSON.stringify({excluded:!excluded,reason})});await renderServerInventory();}catch(error){alert(error.message);}return;}
    if(saveId){const camera=cameras.find(item=>item.id===saveId),overrides={...camera.overrides};for(const key of ["live_interval_minutes","recording_interval_minutes","recording_lookback_hours","recording_expected"]){const input=cameraList.querySelector(`[data-camera="${CSS.escape(saveId)}"][data-setting="${key}"]`);if(key==="recording_expected"){if(input.value==="default")delete overrides[key];else overrides[key]=input.value==="true";}else if(input.value.trim())overrides[key]=Number(input.value);else delete overrides[key];}try{await api(`cameras/${saveId}`,{method:"PUT",body:JSON.stringify({overrides})});await renderServerInventory();}catch(error){alert(error.message);}return;}
    if(!cameraId)return;const output=document.querySelector(`#check-${CSS.escape(cameraId)}`);button.disabled=true;const recording=Boolean(button.dataset.recordingCheck);output.textContent=`Starting ${recording?"recording":"live"} check…`;
    try{const job=await api(`cameras/${cameraId}/${recording?"recording-check":"live-check"}`,{method:"POST",body:"{}"});let latest=job;for(let attempt=0;attempt<80;attempt++){await new Promise(resolve=>setTimeout(resolve,250));latest=await api(`${recording?"recording-checks":"live-checks"}/${job.id}`);if(recording?latest.status==="completed":["succeeded","failed","cancelled"].includes(latest.status))break;}if(recording){const r=latest.result;output.textContent=`Recording ${r?.health||latest.status}${r?.reason?` · ${r.reason.replaceAll("_"," ")}`:""} · newest ${r?.newest_recording_at||"none in window"}`;}else if(latest.status==="succeeded")output.textContent=`Live frames decoded; source timestamp ${latest.result?.freshness_verified===false?"unverified":"verified"}.`;else if(latest.status==="failed")output.textContent=`Live check failed: ${latest.error?.message||"unknown error"}`;}catch(error){output.textContent=error.status===502?"Exacq Web Service returned an error; inspect the connection and capability status.":`Check could not start: ${error.message}`;}finally{button.disabled=false;}
  };
  list.onclick=async event=>{const button=event.target.closest("button[data-action]");if(!button)return;const id=button.dataset.id,action=button.dataset.action;try{if(action==="discover")await api(`servers/${id}/discover`,{method:"POST",body:"{}"});if(action==="recording-check"){const batch=await api(`servers/${id}/recording-check`,{method:"POST",body:"{}"});alert(`Started recording checks for ${batch.jobs.length} camera(s).`);}if(action==="probe")await api(`servers/${id}/capabilities`,{method:"POST",body:"{}"});if(action==="remove"&&confirm("Remove this server and its discovered inventory?"))await api(`servers/${id}`,{method:"DELETE"});if(action==="edit"){const current=servers.find(s=>s.id===id);const name=prompt("Server display name",current.name);if(name===null)return;const host=prompt("Server hostname or IP",current.host);if(host===null)return;const web_scheme=prompt("Web Service scheme (http or https)",current.web_scheme||"http");if(web_scheme===null)return;const web_port=Number(prompt("Web Service port",current.web_port||80));if(!web_port)return;const username=prompt("Username (blank keeps the saved username)","");if(username===null)return;const password=prompt("New password (blank keeps the saved password)","");if(password===null)return;const defaults={...current.defaults};for(const [key,label] of [["live_interval_minutes","Default live interval in minutes"],["recording_interval_minutes","Default recording interval in minutes"],["recording_lookback_hours","Default recording lookback in hours"]]){const value=prompt(label,defaults[key]);if(value===null)return;defaults[key]=Number(value);}defaults.recording_expected=confirm("Should missing recordings raise a warning by default?");await api(`servers/${id}`,{method:"PUT",body:JSON.stringify({name,host,web_scheme,web_port,username,password,defaults})});}}catch(error){alert(error.message);}await renderServerInventory();};
}
async function start() {
  try { sharedBranding = await api("branding"); applyBranding(sharedBranding); const setup = await api("setup/status"); if (setup.setup_required) return renderSetup(); try { await api("auth/me"); return renderDashboard(); } catch (error) { if (error.status === 401) return renderLogin(); throw error; } }
  catch (error) { appRoot.innerHTML = `<section class="auth-card"><p class="eyebrow">CONNECTION ERROR</p><h1>Monitor unavailable</h1><p class="muted">${escapeHtml(error.message)}. Check the service and try again.</p><button class="primary" onclick="location.reload()">Retry</button></section>`; }
}
start();
